    }
    public async ValueTask InitializeRegionAsync()
    {
        var s=await _repository.SnapshotAsync();if(BranchOperations.Entity(s,StateId) is not null){State(s);return;}Safe(s);var hand=ActualArrival(s);Require(new NavigationGrid(Geometry["R4-S01"]).CanStand(Actor(s).Position,true),"实际登陆落点危险。");Require(s.Items.Any(i=>i.Id==SampleId&&i.DefinitionId=="R3-SEALED-VERIFICATION-SAMPLE"&&i.OwnerKind=="player"&&i.OwnerId=="hero"),"真实唯一矿区样本未随本次交接保留。");var changes=ImmutableArray.CreateBuilder<EntityChange>();changes.Add(Change(s,new(){ContentVersion=Package.Version}));foreach(string q in MainQuests)changes.Add(BranchOperations.Change(s,"quest:"+q,"quest",new QuestState(q,Guid.NewGuid(),q is "Q-401" or "Q-402"?QuestLifecycle.Active:QuestLifecycle.Unaccepted,null)));changes.Add(BranchOperations.Change(s,"quest:CQ-MIRA-02","quest",new QuestState("CQ-MIRA-02",Guid.NewGuid(),QuestLifecycle.Unaccepted,null)));changes.Add(BranchOperations.Change(s,"R4:sample_expected","sample_expectation",hand));changes.Add(BranchOperations.Change(s,"R4:calibration_marks","calibration_marks",new{zero=0,reference=10,instrument_revision=0}));var result=await Commit(s,"glasshaven_region_initialized",changes.ToImmutable(),new{scope="original_unreviewed_runtime_candidate",experience_awarded=0,sample_received=false},"R4:initialize:"+Package.Version);Require(result.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,"学城初始化未提交。");
    }
    private bool Calibrated(ChapterFourState st)=>st.ZeroCheckRevision==st.InstrumentRevision&&st.ReferenceCheckRevision==st.InstrumentRevision;
    private bool Prepared(BranchSnapshot s,ChapterFourState st)=>Closed(s,"Q-401")&&Closed(s,"Q-402")&&Result(s,"ENC-R4-03")&&st.IslandIsolation&&st.IslandGuard&&Calibrated(st)&&st.ConfigurationCheckRevision==st.IslandRevision&&st.IslandLoad is 40 or 70&&st.IslandContact=="limited"&&st.TrialOperator=="N-SIAN"&&st.TrialReviewer=="ROLE-R4-TRIAL-REVIEW";
    private static bool OutputChecked(ChapterFourState st)=>st.OutputIsolated&&st.OutputRoute=="TEST"&&st.CouplerSeated&&st.OutputGuard&&st.OutputCheckRevision==st.OutputRevision;
    private ImmutableArray<EntityChange> GateChanges(BranchSnapshot s,ImmutableArray<EntityChange> changes)
    {
        var change=changes.SingleOrDefault(c=>c.Id==StateId);var st=change is null?BranchOperations.Read<ChapterFourState>(s,StateId):StrictJson.Deserialize<ChapterFourState>(change.Json);if(st is null)return changes;bool Has(string id)=>Result(s,id)||changes.Any(c=>c.Id=="R4:result:"+id&&StrictJson.Deserialize<GlasshavenEncounterResult>(c.Json).Completed);
        var gates=new Dictionary<string,bool>{{"sample_receiving_route",st.SampleReceived},{"public_data",true},{"custodian_bounded_review",st.ReportScope},{"onsite_trial_safety_permit",st.OldPermit},{"old_facility_isolated_safe",st.OldIsolated&&Has("ENC-R4-01")&&Has("ENC-R4-02")},{"current_island_configuration_ready",Prepared(s,st)||st.FieldEntryAuthorized},{"post_trial_logistics_latch",st.LogisticsLatch},{"tower_work_permit",st.PrismPermit},{"report_review_passage",st.ReportScope&&st.PrismPermit},{"public_student_room",true},{"public_exhibition",true}};var output=changes.ToBuilder();foreach(var gate in gates){string id="R4:gate:"+gate.Key;var old=BranchOperations.Read<GlasshavenGate>(s,id);if(old is null||old.Allowed!=gate.Value)output.Add(BranchOperations.Change(s,id,"chapter_gate",new GlasshavenGate(gate.Key,gate.Value,Package.Version)));}return output.ToImmutable();
    }
    public ImmutableDictionary<string,SceneGeometry> CurrentGeometry(BranchSnapshot s){var st=State(s);return Package.Scenes.ToImmutableDictionary(x=>x.Geometry.Id,x=>x.Geometry with{Danger=x.Hazards.Where(h=>h.Id switch{"R4-S05.old_residual_zone"=>!st.OldIsolated||!Result(s,"ENC-R4-01")||!Result(s,"ENC-R4-02"),"R4-S06.calibration_defence_zone"=>!Result(s,"ENC-R4-03"),"R4-S07.execution_output_zone"=>!Result(s,"ENC-R4-04")||!OutputChecked(st),_=>true}).Select(h=>h.Area).ToImmutableArray()});}
    public async ValueTask<ImmutableDictionary<string,SceneGeometry>> CurrentGeometryAsync()=>CurrentGeometry(await _repository.SnapshotAsync());
    private void At(BranchSnapshot s,string spot){var actor=Actor(s);var geometry=CurrentGeometry(s);Require(geometry.TryGetValue(actor.Scene,out var scene)&&scene.Spots.Any(p=>p.Id==spot&&actor.Position.Distance(p.Stand)<=2.5)&&new NavigationGrid(scene).CanStand(actor.Position,true),"请先走到当前真实安全操作站位。");}
