        if(m.Quest=="Q-404"){var facility=BranchOperations.Read<GlasshavenRecordScope>(s,"R4:facility_scope");return facility is{Report:"F-17",Version:"1",Recipient:"patrol_technician",Purpose:"verify_holding_facility",Grantor:"R4-records-custodian"}&&new[]{"facility_code","supply_destination","watch_post","version_source"}.All(facility.Fields.Contains);}
        var scope=BranchOperations.Read<GlasshavenRecordScope>(s,"R4:report_scope");return scope is{Report:"GH-R7",Version:"7",Recipient:"patrol_technician",Purpose:"verify_public_data",Grantor:"R4-records-custodian"}&&new[]{"observation_ids","test_conditions","outcomes","issue_version","circulation_dates"}.All(scope.Fields.Contains);
    }
    private bool Sources(BranchSnapshot s,params string[] ids)=>ids.All(id=>Package.Materials.SingleOrDefault(m=>m.Id==id) is{} m&&Acquired(s,m)&&Accessible(s,m));
