    public async ValueTask<ChapterFourView> ViewAsync(){var s=await _repository.SnapshotAsync();var actor=Actor(s);return new(s,actor,State(s),MainQuests.Append("CQ-MIRA-02").Select(q=>Quest(s,q)!).ToImmutableArray(),Package.Materials.Where(m=>Acquired(s,m)&&Accessible(s,m)).ToImmutableArray(),Package.Stations.Where(st=>st.Spot.StartsWith(actor.Scene+'.',StringComparison.Ordinal)).ToImmutableArray(),CurrentGeometry(s),Runs(s));}
    public async ValueTask TraverseAsync(ImmutableArray<Point2> path){if(path.IsDefaultOrEmpty)return;var s=await _repository.SnapshotAsync();Safe(s);var a=Actor(s);var nav=new NavigationGrid(CurrentGeometry(s)[a.Scene]);var from=a.Position;foreach(var to in path){Require(nav.SegmentClear(from,to,true),"路径穿过真实障碍或未处置危险。");from=to;}var result=await Commit(s,"glasshaven_walk",[BranchOperations.Change(s,"actor","actor",a with{Position=from,ActionClock=checked(a.ActionClock+1)})],new{actual_path=path});Require(result.Status is CommitStatus.Committed or CommitStatus.AlreadyCommitted,"当前状态变化，移动未提交。");}
    public async ValueTask MoveAsync(Point2 point)=>await TraverseAsync([point]);
