    }
    public async ValueTask<CommandResult> DiscoverAsync(string id){var s=await _repository.SnapshotAsync();Safe(s);var material=Package.Materials.Single(m=>m.Id==id);At(s,material.Spot);Require(Accessible(s,material),"当前具体材料访问范围尚未成立。");if(Acquired(s,material))return new(CommitStatus.AlreadyCommitted,null,[]);return await Commit(s,"glasshaven_material_acquired",[BranchOperations.Change(s,"material:"+id,"material_access",new ChapterMaterialAccess(id,material.Version,material.TranslationVersion,material.Fingerprint,material.SourceRoot,material.Spot))],new{material=id,source_root=material.SourceRoot,source_channel=material.Kind=="listening_script"?"written_transcript_only":"written_original",audio_listened=false},"material:"+id+":acquired");}
